import React from "react";
import { useQuery, gql } from "@apollo/client";
import { Helmet } from "react-helmet";
import ReactMarkdown from "react-markdown";
import DOMPurify from "dompurify";

const GET_PAGE = gql`
  query {
    page(id: 1) {
      data {
        id
        attributes {
          name
          text
        }
      }
    }
  }
`;

export default function Homepage() {
  const { data, loading, error } = useQuery(GET_PAGE);

  if (loading) return <p>Loading...</p>;
  if (error) return <p>Error loading content</p>;

  const rawContent = data?.page?.data?.attributes?.text;

  // --- Helper: Check if content is a string ---
  const isString = typeof rawContent === "string";

  // --- Helper: Check if content is JSON (Array of objects) ---
  const isRichTextJSON =
    Array.isArray(rawContent) &&
    rawContent.every((block) => typeof block === "object" && block.children);

  // --- Function to render Strapi JSON Rich Text safely ---
  const renderRichText = (blocks) => {
    return blocks.map((block, i) => {
      if (block.type === "paragraph") {
        return (
          <p key={i}>
            {block.children.map((child, j) => (
              <span key={j}>{child.text}</span>
            ))}
          </p>
        );
      }

      if (block.type === "heading") {
        return (
          <h2 key={i}>
            {block.children.map((child, j) => (
              <span key={j}>{child.text}</span>
            ))}
          </h2>
        );
      }

      return null; // Skip unsupported block types for now
    });
  };

  return (
    <div className="textelement">
      <Helmet>
        <title>De Groep | Scouts 121 Oude-God Mortsel</title>
        <meta
          name="description"
          content="Scouts 121 Scouts 121 bestaat sinds 2014 en is ontstaan uit de fusie van twee oudere scoutsen, namelijk scouts 115 en scouts 144..."
        />
        <meta
          name="keywords"
          content="contact, contacteren, e-mail, scouts121, 121, scouts"
        />
        <meta name="HandheldFriendly" content="true" />
      </Helmet>

      {/* --- Render content based on format --- */}
      {isString ? (
        rawContent.includes("#") || rawContent.includes("*") ? (
          // If it's Markdown → Render with ReactMarkdown
          <ReactMarkdown>{rawContent}</ReactMarkdown>
        ) : (
          // Else assume HTML → Sanitize and render safely
          <div
            dangerouslySetInnerHTML={{
              __html: DOMPurify.sanitize(rawContent),
            }}
          />
        )
      ) : isRichTextJSON ? (
        // If Strapi returns JSON → Render blocks
        <div>{renderRichText(rawContent)}</div>
      ) : (
        <p>Geen inhoud beschikbaar</p>
      )}
    </div>
  );
}
